import Foundation
@testable import BookmaniaCore

/// Test books generated by `core/ebook/testbooks/make_testbooks.py`, shared with the Android unit tests.
enum Fixtures {
    static let directory: URL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent() // BookmaniaCoreTests
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // BookmaniaCore
        .deletingLastPathComponent() // ios
        .deletingLastPathComponent() // repository root
        .appendingPathComponent("core/ebook/src/test/resources/fixtures")

    static func url(_ name: String) -> URL { directory.appendingPathComponent(name) }

    static func source(_ name: String) throws -> RandomAccessSource { try FileSource(url: url(name)) }

    static func bytes(_ name: String) throws -> [UInt8] { [UInt8](try Data(contentsOf: url(name))) }
}

/// Runs `body` and returns the BookError it throws, or nil.
func bookError(_ body: () throws -> Void) -> BookError? {
    do {
        try body()
        return nil
    } catch let e as BookError {
        return e
    } catch {
        return .corrupt("unexpected error \(error)")
    }
}
